glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
in vec3 a_position;
in vec4 a_color;
in vec2 a_uv0;
out vec4 v_color;
out vec2 v_uv0;
void main() {
  vec4 pos = vec4(a_position, 1.0);
  #if CC_USE_MODEL
    pos = cc_matViewProj * cc_matWorld * pos;
  #else
    pos = cc_matViewProj * pos;
  #endif
  gl_Position = pos;
  v_color = a_color;
  v_uv0 = a_uv0;
}

glsl3.frag:
precision highp float;
in vec4 v_color;
in vec2 v_uv0;
uniform sampler2D texture;
uniform sampler2D maskTexture;
uniform ScratchReveal {
  vec4 maskUVRect;
  float maskThreshold;
};
void main() {
  vec2 temp = v_uv0;
  temp.y = 1.0 - temp.y;
  vec2 maskUV = maskUVRect.xy + temp * maskUVRect.zw;
  vec4 inputValue = texture2D(maskTexture, maskUV);
  vec4 normalValue = texture2D(texture, v_uv0);
  vec4 o = vec4(1, 1, 1, 0);
  #if USE_TEXTURE
  vec4 texture_tmp = texture(texture, v_uv0);
  #if CC_USE_ALPHA_ATLAS_texture
      texture_tmp.a *= texture(texture, v_uv0 + vec2(0, 0.5)).r;
  #endif
  #if INPUT_IS_GAMMA
    o.rgb *= (texture_tmp.rgb * texture_tmp.rgb);
    o.a *= texture_tmp.a;
  #else
    o *= texture_tmp;
  #endif
  #endif
  o *= v_color;
  if (inputValue.a > 0.0) {
    gl_FragColor = normalValue.rgba;
  } else {
    gl_FragColor = o.rgba;
  }
}

